INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ('kb-iso9999','ISO 9999:2022 — Phân loại công nghệ hỗ trợ (đã chuẩn hoá mã)','ISO 9999:2022 — Phân loại công nghệ hỗ trợ','ISO 9999:2022 phân loại AT theo chức năng cơ thể. Ví dụ: 12.21 (xe lăn), 21.21 (máy trợ thính), 22.06 (thiết bị hỗ trợ thị giác), 22.03 (thiết bị hỗ trợ cảm giác cho người mù), 07.32 (thiết bị giao tiếp AAC). Mỗi mã có phân lớp cụ thể.','mada-curated','manual',NULL,NULL,'education','["ISO 9999:2022"]','',NULL,0,0,'published',3,'vi','{"source":"seed"}',1,'2026-10-22T04:59:19.886Z','data_manager-1792403329808-qwvke3','2026-10-07T04:59:19.886Z','2026-10-23 06:26:53','ISO 9999:2022 — Phân loại công nghệ hỗ trợ','ISO 9999:2022 — Phân loại công nghệ hỗ trợ','ISO 9999:2022 — Phân loại công nghệ hỗ trợ','ISO 9999:2022 — Phân loại công nghệ hỗ trợ',NULL,NULL,'ISO 9999:2022 phân loại AT theo chức năng cơ thể. Ví dụ: 12.21 (xe lăn), 22.06 (thiết bị thính giác), 22.03 (thiết bị thị giác), 22.09 (thiết bị truyền thông). Mỗi code có subclass cụ thể.','','',1);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ('kb-jaws-nvda','So sánh JAWS, NVDA, VoiceOver','So sánh JAWS, NVDA, VoiceOver','JAWS (Freedom Scientific, Windows, $1100/năm) — giàu tính năng doanh nghiệp. NVDA (NV Access, miễn phí, Windows) — open source, phổ biến ở Châu Á. VoiceOver (Apple, tích hợp iOS/macOS) — đồng bộ tốt với hệ sinh thái Apple.','mada-curated','manual',NULL,NULL,'vision','["22.06.12"]','',NULL,0,0,'published',3,'vi','{"source":"seed"}',1,'2026-10-22T04:59:19.887Z','data_manager-1792403329808-qwvke3','2026-10-07T04:59:19.887Z','2026-10-22T04:59:19.887Z','So sánh JAWS, NVDA, VoiceOver','So sánh JAWS, NVDA, VoiceOver','So sánh JAWS, NVDA, VoiceOver','So sánh JAWS, NVDA, VoiceOver',NULL,NULL,'JAWS (Freedom Scientific, Windows, $1100/năm) — giàu tính năng doanh nghiệp. NVDA (NV Access, miễn phí, Windows) — open source, phổ biến ở Châu Á. VoiceOver (Apple, tích hợp iOS/macOS) — đồng bộ tốt với hệ sinh thái Apple.','','',1);
