INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ('kb-cognitive-aid','Thiết bị hỗ trợ trí nhớ MCI','Thiết bị hỗ trợ trí nhớ MCI','MCI (Mild Cognitive Impairment) — thiết bị phù hợp: đồng hồ nói, lịch điện tử, app reminder (Medisafe, Pillboxie), thiết bị định vị (GPS), và smart home (Google Home, Alexa) cho nhắc việc.','mada-curated','manual',NULL,NULL,'cognition','["22.27.16"]','',NULL,0,0,'published',3,'vi','{"source":"seed"}',1,'2026-10-22T04:59:19.887Z','data_manager-1792403329808-qwvke3','2026-10-07T04:59:19.887Z','2026-10-22T04:59:19.887Z','Thiết bị hỗ trợ trí nhớ MCI','Thiết bị hỗ trợ trí nhớ MCI','Thiết bị hỗ trợ trí nhớ MCI','Thiết bị hỗ trợ trí nhớ MCI',NULL,NULL,'MCI (Mild Cognitive Impairment) — thiết bị phù hợp: đồng hồ nói, lịch điện tử, app reminder (Medisafe, Pillboxie), thiết bị định vị (GPS), và smart home (Google Home, Alexa) cho nhắc việc.','','',1);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ('debe74bf-cb0a-41ac-a2d9-d81bca127563','Scraped: MADA Main Website','# Mada Assistive Technology Portal is the first digital platform specialized in assistive technology in Arabic. The portal provides a wide range of information, resources and assistive technology services to enable and support the independence of persons with disabilities through accessible information and communication technology ICT.

## Nội dung chính

Mada Assistive Technology Portal is the first digital platform specialized in assistive technology in Arabic. The portal provides a wide range','# Mada Assistive Technology Portal is the first digital platform specialized in assistive technology in Arabic. The portal provides a wide range of information, resources and assistive technology services to enable and support the independence of persons with disabilities through accessible information and communication technology ICT.

## Nội dung chính

Mada Assistive Technology Portal is the first digital platform specialized in assistive technology in Arabic. The portal provides a wide range of information, resources and assistive technology services to enable and support the independence of persons with disabilities through accessible information and communication technology ICT. Assistive Technology by Body Function Assistive technology provides a wide range of solutions for people who have disabilities and functional limitations in human senses such as vision, hearing, communication, mobility and cognition, to improve their functional abilities. Sensory – Hearing Assistive technology for persons with hearing impairment either amplifies sound or converts it into visual or tactile signals. These products are designed to assist deaf and hard-of-hearing people who need help with communication, access to media, and awareness of the sounds around them. Discover more Sensory – Vision Assistive technology for persons with visual impairment supports visual stimuli such as the sense of shape, size and color. Individuals who may benefit from this technology include blind persons, persons with low vision, or with conditions limiting their ability to recognize visual stimuli. Discover more Voice and Speech Assistive technology for verbal communication, also known as augmentative and alternative communication (AAC) devices, help people with speech difficulties communicate verbally or face to face. Discover more Mental – Cognitive Assistive technology for persons with cognitive limitations supports mental functions such as memory, language, calculation, and organization. Discover more Neuromusculoskeletal Movement Assistive technology for persons with limited functions of joints, bones, reflexes and muscles supports their movement, access and mobility Discover more Assistive Technology by Activities and Participation Assistive technology provides a wide range of solutions for people with disabilities to support their independence and participation in various tasks and activities in their life areas such as education, employment and society. Mobility and Transportation Assistive technology for mobility and transportation help persons with limitations for moving around or transferring from one place to another. Discover more Self-care Assistive technology for self-care helps individuals complete everyday essential activities such as dressing, bathing, eating, cleaning, or meal preparation. Discover more Recreation and Leisure Assistive technology for recreation and leisure provides accessible solutions to participate in and enjoy leisure activities such as gaming, listening to audio content, or watching TV. Discover more Communication Assistive technology for communication assists people communicating in multiple ways such as verbal, text, video, signs and symbols. Discover more Education Assistive technology for education enables students to engage in inclusive learning environments and enhance opportunities for lifelong learning. Discover more Employment Assistive technology for employment enables persons with disabilities to engage in work and jobs to improve their accessibility, productivity, and independence. Discover more Interpersonal interactions and relationships Assistive technology for interpersonal interactions and relationships assists managing person’s emotion, social, and behavior to increase appropriate social interactions and participations. Discover more Environmental Control Assistive technology for environmental control assists persons to facilitate manipulation and operation of various devices in the home, workplace, and in public. Discover more Success Stories Meet Hamad 12-year-old Hamad was diagnosed with Cerebral Palsy, a condition that limits his mobility. Simple tasks like studying, moving, and gaming with friends were highly challenging. We at Mada offered Hamad various assistive technologies that facilitated his day-to-day tasks. Hamad today dreams of becoming the first Qatari to start a YouTube gaming channel. Meet Saoud Saoud is a young adult in a wheelchair who has Cerebral Palsy. Saoud is a highly motivated and committed individual with excellent people skills and a genuine interest in helping others. He joined the Access to Employment Program offered by Mada in 2018 and is working now as a receptionist at Um Salal Primary School. Saoud uses Arabic BigKeys with a keyguard and a joystick mouse to access the computer and perform his daily tasks. View All Skip back to main navigation


Assistive Technology Assistive Technology (AT) is any item, software, piece of equipment, or product system, whether acquired commercially, modified, or customized, that is used to increase, maintain, or improve the functional capabilities of individuals with disabilities. You can learn more about AT terms by visiting Mada Accessibility & AT Glossary page. The International Classification of Functioning, Disability, and Health (ICF) provides a framework for describing and organizing information on functioning and disability. Mada AT category classifications has been developed according to the International Classification of Functioning, Disability, and Health (ICF) domains part (1) issued by the World Health Organization, which includes two components: First: Body Functions Second: Activities and Participation Please visit the ICF webpage to learn about the ICF. Please click on the relevant link below to learn more about Assistive Technology. Assistive Technology by Body Functions Assistive technology provides a wide range of solutions for people who have disabilities and functional limitations in human senses such as vision, hearing, communication, mobility and cognition, to improve their functional abilities. Sensory – Hearing Assistive technology for persons with hearing impairment either amplifies sound or converts it into visual or tactile signals. These products are designed to assist deaf and hard-of-hearing people who need help with communication, access to media, and awareness of the sounds around them. Discover more Sensory – Vision Assistive technology for persons with visual impairment supports visual stimuli such as the sense of shape, size and color. Individuals who may benefit from this technology include blind persons, persons with low vision, or with conditions limiting their ability to recognize visual stimuli. Discover more Voice and Speech Assistive technology for verbal communication, also known as augmentative and alternative communication (AAC) devices, help people with speech difficulties communicate verbally or face to face. Discover more Mental – Cognitive Assistive technology for persons with cognitive limitations supports mental functions such as memory, language, calculation, and organization. Discover more Neuromusculoskeletal Movement Assistive technology for persons with limited functions of joints, bones, reflexes and muscles supports their movement, access and mobility Discover more Assistive Technology by Activities and Participation Assistive technology provides a wide range of solutions for people with disabilities to support their independence and participation in various tasks and activities in their life areas such as education, employment and society. Mobility and Transportation Assistive technology for mobility and transportation help persons with limitations for moving around or transferring from one place to another. Discover more Self-care Assistive technology for self-care helps individuals complete everyday essential activities such as dressing, bathing, eating, cleaning, or meal preparation. Discover more Recreation and Leisure Assistive technology for recreation and leisure provides accessible solutions to participate in and enjoy leisure activities such as gaming, listening to audio content, or watching TV. Discover more Communication Assistive technology for communication assists people communicating in multiple ways such as verbal, text, video, signs and symbols. Discover more Education Assistive technology for education enables students to engage in inclusive learning environments and enhance opportunities for lifelong learning. Discover more Employment Assistive technology for employment enables persons with disabilities to engage in work and jobs to improve their accessibility, productivity, and independence. Discover more Interpersonal interactions and relationships Assistive technology for interpersonal interactions and relationships assists managing person’s emotion, social, and behavior to increase appropriate social interactions and participations. Discover more Environmental Control Assistive technology for environmental control assists persons to facilitate manipulation and operation of various devices in the home, workplace, and in public. Discover more Skip back to main navigation


AT Services The Mada Center is dedicated to enabling individuals with disabilities to enhance their independence with the use of assistive technology. We offer a range of Assistive Technology services, including AT evaluation, provision of AT, training, and technical support. Through our AT services, we provide expert advice, consultations, and technical support for assistive technology devices and solutions, helping people with disabilities to harness the power of AT to enhance their quality of life. Mada Center offers Assistive Technology Assessment Services to support persons with disabilities by assessing their needs of assistive technology and offering support services.​ Captcha Skip back to main navigation


Where to try Assistive Technology in Qatar To learn more about the latest Assistive Technology, please visit the Mada Innovation Lab located on the 7th Floor of Al Nasr tower B on Asia Street, Corniche Area. Mada has enabled a variety of AT stations in Qatar to demonstrate a wide range of assistive technologies for AT users within the centers and institutes. Education Digital Inclusive education is one of the priority sectors in Mada’s strategy. We believe that education offers vast possibilities for a positive impact on students with disabilities and is an essential element of integration and social inclusion because it removes any barriers limiting student’s abilities and competencies. Therefore MADA partnered with key education sectors in Qatar to install various AT stations to cater for the needs of students with a large spectrum of disabilities like Autism, Learning difficulties, Communication Difficulties, Access Limitations, Hearing and Visual Difficulties, etc.… to facilitate their access to education. If you are a student or a parent of a student, you can find more information about those AT stations below. Roua Center Address: Al Thumama, Ibn Al Baitar Street Phone: +974-40129195 Email: roua.aasc@edu.gov.qa Qatar University Address: Dafna, Al Jamiaa Street Phone: +974-44033333 Email: info@qu.edu.qa Al Shafallah Center Station 1: Speech Therapy Department Station 2: Portage program Station 3: Library Department Station 4: School Unit 1 Station 5: Daily Care unit Station 6: Vocational Training Department Station 7: Autism Department Address: Lusail Phone: +974-44956666 Email: info@shafallah.org.qa Al Noor Center For The Blind (School Kits) Address: Lusail Phone: +974-44222777 Email: alnoorcenter@alnoor.org.qa Community College of Qatar Address:Lusail Male Campus, P.O.Box: 7344, Losail City, Doha Qatar Phone: +974 44011400 Email: talabi@ccq.edu.qa Qatar Foundation-Awsaj Academy (School Kits) Address:Awsaj Academy, Education City, Al-Rayyan, Doha, Qatar Phone: +974 44542111 Email: awsajacademy@qf.org.qa Qatar Foundation – The Learning Center (School Kits) Address:Al Luqta Street, Education City – Qatar Academy Doha Phone: +974 445 42106 Email: ccherian@qf.org.qa Qatar Foundation – Renad Academy (School Kits) Address:Bani Hajer, Zone Number: 51, Street Name: 1264, Building number 16 Phone: +974 4454 5874 Email: bfabian@qf.org.qa Training and Educational Development Centre Address:Alnuaimi, Alnuaimi Area, Doha Qatar Phone: +974 44045115 Email: tedc@edu.gov.qa Al-Hedayah Kindergarten for Special Needs-Dahl El Hamam Address:Dahl Al Hamam, Doha Phone:44880878 Email: alhedaya@edu.sec.gov.qa Al-Hedayah School Al Thumama Address:Althumam, Doha Phone: 4499 6466 Email: AlHidaya-SN@edu.gov.qa Al-Hedayah School Alsakhama Address: Alsakhama, Doha Phone: 4404 2483 Email: alhidaya-alsakhama@edu.gov.qa Al-Hedayah School Al Hilal Address: Qatar, Doha, Madinat Khalifa Phone: 4036 9877 Email: alhidaya-alhilal@edu.gov.qa AL Yarmouk Boys School Address:Qatar, Doha, Fereej Bin Omran Phone: 44868058 Email: albayan-complex@edu.gov.qa Roqaya Preparatory for Girls Independent School Address:Wholesale Market Street Phone: 44598500 Email: roqayya@edu.gov.qa Community and Culture Through its strategic partnership with essential community and culture sectors in Qatar, MADA launched several AT stations in different locations to promote an inclusive and accessible community for all people with disabilities and to ensure accessible government services, accessible retail services, accessible health services and accessible media services. If you are a person with a disability or a parent of a PWD, you can find more information about those AT stations below. Qatar Rehabilitation Institute (QRI) Address:Hamad Bin Khalifa Medical City, Building 24, Doha – Qatar Phone: +974-44395777 Email: nesmaak@hamad.qa Center for Empowerment and Care of the Elderly (Ehsan) Address:Third Ring Road, Doha – Qatar Phone: +974-40121000 Email: media@ehsan.org.qa Child Development Center (CDC) Address:RH in front of NCCR Hospital, Hamad Bin Khalifa Medical City, Doha – Qatar Phone: +974-40256349 / +974-40256334 Email: nesmaak@hamad.qa Sidra Medicine Address: Al Gharrafa Street, Ar-Rayyan, Doha, Qatar Phone: +974-40033333 Email: info@sidra.org Ministry of Interior Address: Annex Administrative complex, Onaiza Road, Doha Phone: 2367111 Email: info@moi.gov.qa Qatar National Library Address:Qatar National Library, Education City, Doha, Qatar Phone: 4454 0100 Email: qnl@qnl.qa Primary Health Care Corporation Address:P.O. Box 26555, Doha, Qatar Phone: 402-71250 Email: lsaranek@phcc.gov.qa Skip back to main navigation


