INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ('reg-wcag-22-overview','WCAG 2.2 — Nguyên tắc và 4 mức tuân thủ (A, AA, AAA)','Web Content Accessibility Guidelines 2.2 của W3C: 4 nguyên tắc (Perceivable, Operable, Understandable, Robust) và 3 mức tuân thủ A/AA/AAA.','WCAG 2.2 (Web Content Accessibility Guidelines) là bộ tiêu chuẩn quốc tế của W3C về khả năng tiếp cận nội dung số, áp dụng cho website, ứng dụng web và nội dung điện tử.

BỐN NGUYÊN TẮC (POUR):
1. Perceivable (Có thể nhận biết): thông tin phải trình bày bằng văn bản thay thì cho hình ảnh, video, âm thanh; tương phản màu đủ cao; hỗ trợ tùy biến kích thước chữ.
2. Operable (Có thể thao tác): mọi chức năng phải dùng được bằng bàn phím; không có thành phần gây nháy dị ứng; cung cấp thời gian đủ để thao tác; có cơ chế tháo gỡ nguy hiểm.
3. Understandable (Dễ hiểu): ngôn ngữ rõ ràng, điều hướng nhất quán, hỗ trợ nhập liệu và xác nhận thông tin.
4. Robust (Chắc chắn): tương thích với trình duyệt và công nghệ trợ giúp hiện đại (screen reader, bàn phím lớn, thiết bị chuyển động mắt).

BA MỨC TUÂN THỦ:
- Mức A (Level A): các yêu cầu cơ bản, bắt buộc tối thiểu. Đây là mức mà WCAG 1.0/1.1/1.2 đã đòi hỏi.
- Mức AA (Level AA): khuyến nghị. Là mức mà hầu hết tổ chức, các cơ quan nhà nước và các trường hợp thường yêu cầu khi giao dịch trực tuyến.
- Mức AAA (Level AAA): mức cao nhất, bao gồm ngôn ngữ đơn giản, chữ đọc dễ hiểu và hỗ trợ người mù hoàn toàn. Thường rất khó đạt đồng thời.

LƯU Ý: Mức tuân thủ được xếp theo thứ bực — đạt AAA đồng nghĩa đạt AA và A. Đạt AA là mục tiêu thực tế phổ biến nhất cho các tổ chức.

ÁP DỤNG: WCAG áp dụng cho website, ứng dụng di động và bất kỳ nội dung số nào người dùng cần tiếp cận được bằng công nghệ trợ giúp.','https://www.w3.org/TR/WCAG22/','web','https://www.w3.org/TR/WCAG22/',NULL,'web_accessibility','[]',NULL,NULL,0,0.95,'published',2,'vi','{"botId":"bot-regulatory","madaCategory":"regulatory-standards","sourceCategory":"web_accessibility","keywords":"wcag, web content accessibility, pour, perceivable, operable, understandable, robust, mức a aa aaa, tuân thủ","seededBy":"seed-regulatory-knowledge"}',0,NULL,'admin-1792403329191','2026-10-23T06:23:43.363Z','2026-10-23T06:23:43.363Z','WCAG 2.2 — Principles and four conformance levels (A, AA, AAA)','','','Web Content Accessibility Guidelines 2.2 của W3C: 4 nguyên tắc (Perceivable, Operable, Understandable, Robust) và 3 mức tuân thủ A/AA/AAA.',NULL,NULL,'WCAG 2.2 (Web Content Accessibility Guidelines) là bộ tiêu chuẩn quốc tế của W3C về khả năng tiếp cận nội dung số, áp dụng cho website, ứng dụng web và nội dung điện tử.

BỐN NGUYÊN TẮC (POUR):
1. Perceivable (Có thể nhận biết): thông tin phải trình bày bằng văn bản thay thì cho hình ảnh, video, âm thanh; tương phản màu đủ cao; hỗ trợ tùy biến kích thước chữ.
2. Operable (Có thể thao tác): mọi chức năng phải dùng được bằng bàn phím; không có thành phần gây nháy dị ứng; cung cấp thời gian đủ để thao tác; có cơ chế tháo gỡ nguy hiểm.
3. Understandable (Dễ hiểu): ngôn ngữ rõ ràng, điều hướng nhất quán, hỗ trợ nhập liệu và xác nhận thông tin.
4. Robust (Chắc chắn): tương thích với trình duyệt và công nghệ trợ giúp hiện đại (screen reader, bàn phím lớn, thiết bị chuyển động mắt).

BA MỨC TUÂN THỦ:
- Mức A (Level A): các yêu cầu cơ bản, bắt buộc tối thiểu. Đây là mức mà WCAG 1.0/1.1/1.2 đã đòi hỏi.
- Mức AA (Level AA): khuyến nghị. Là mức mà hầu hết tổ chức, các cơ quan nhà nước và các trường hợp thường yêu cầu khi giao dịch trực tuyến.
- Mức AAA (Level AAA): mức cao nhất, bao gồm ngôn ngữ đơn giản, chữ đọc dễ hiểu và hỗ trợ người mù hoàn toàn. Thường rất khó đạt đồng thời.

LƯU Ý: Mức tuân thủ được xếp theo thứ bực — đạt AAA đồng nghĩa đạt AA và A. Đạt AA là mục tiêu thực tế phổ biến nhất cho các tổ chức.

ÁP DỤNG: WCAG áp dụng cho website, ứng dụng di động và bất kỳ nội dung số nào người dùng cần tiếp cận được bằng công nghệ trợ giúp.','','',0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ('reg-wcag-22-new-criteria','WCAG 2.2 — 9 tiêu chí mới so với WCAG 2.1','Danh sách 9 tiêu chí thành công mới được thêm vào WCAG 2.2: Focus Not Obscured, Dragging Movements, Consistent Help, Redundant Entry, Accessible Authentication và các thay đổi khác.','WCAG 2.2 bổ sung 9 tiêu chí thành công mới so với WCAG 2.1, tập trung vào các vấn đề thực tế thường gặp:

1. 2.4.11 Focus Not Obscured (Not Obscured Minimum) — Phần tử đang nhận focus không được bị che khuất bởi nội dung khác (ví dụ popup, banner).
2. 2.4.12 Focus Not Obscured (Enhanced) — phiên bản nghiêm ngặt hơn: không phần tử nào che khuất được phần tử nhận focus.
3. 2.5.7 Dragging Movements — mọi chức năng kéo-thả phải có thao tác thay thế bằng một điểm chạm đơn (quan trọng với người dùng run tay, cứng ngón, rung).
4. 2.5.8 Target Size (Minimum) — vùng bấm phải đủ lớn, tối thiểu 24×24 điểm ảnh (trừ các ngoại lệ như nội dung dòng chữ, liên kết trong câu).
5. 3.2.6 Consistent Help — cơ chế trợ giúp (mục liên hệ, chat, FAQ) phải xuất hiện ở cùng vị trí trên tất cả các trang.
6. 3.3.7 Redundant Entry — không bắt nhập lại thông tin đã có trong cùng quy trình (ví dụ thông tin địa chỉ ở bước thanh toán).
7. 3.3.8 Accessible Authentication (Minimum) — không yêu cầu người dùng nhập lại mật khẩu hay giải puzzle, trừ khi chứng minh là biện pháp bảo mật bắt buộc.
8. 3.3.9 Accessible Authentication (Enhanced) — phiên bản nghiêm ngặt hơn, loại bỏ mọi thao tác nhận dạng bằng nhận thức (ghi nhớ hay sao chép).
9. 4.1.1 Parsing — mã nguồn phải phân tích được không lỗi, loại bỏ lỗi cũ như thẻ đóng không khớp.

Ngoài ra một số tiêu chí cũ được nâng cấp: 2.2.2 Pause, Stop, Hide (khoảng thời gian cho động nội dung tự động kéo dài hơn), 2.3.3 Animation from Interactions, 2.4.7 Focus Visible, 2.4.11 và 3.2.2 On Input.

TÁC ĐỘNG THỰC TẾ: hầu hết thay đổi liên quan đến tương tác kéo-thả, xác thực và kích thước vùng chạm — đây chính là các trở ngại thường gặp với người dùng khuyết tật vận động và thị giác, nên WCAG 2.2 được xem là bản cải thiện đáng kể.','https://www.w3.org/TR/WCAG22/#new','web','https://www.w3.org/TR/WCAG22/#new',NULL,'web_accessibility','[]',NULL,NULL,0,0.95,'published',2,'vi','{"botId":"bot-regulatory","madaCategory":"regulatory-standards","sourceCategory":"web_accessibility","keywords":"wcag 2.2 mới, dragging, target size, consistent help, redundant entry, accessible authentication, focus not obscured","seededBy":"seed-regulatory-knowledge"}',0,NULL,'admin-1792403329191','2026-10-23T06:23:43.363Z','2026-10-23T06:23:43.363Z','WCAG 2.2 — Nine new success criteria compared to WCAG 2.1','','','Danh sách 9 tiêu chí thành công mới được thêm vào WCAG 2.2: Focus Not Obscured, Dragging Movements, Consistent Help, Redundant Entry, Accessible Authentication và các thay đổi khác.',NULL,NULL,'WCAG 2.2 bổ sung 9 tiêu chí thành công mới so với WCAG 2.1, tập trung vào các vấn đề thực tế thường gặp:

