INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ('reg-atsm-qatar','ATSM Qatar — Tiêu chuẩn MADA và khung pháp lý tại Qatar','Giới thiệu khung tiêu chuẩn ATSM của Qatar về công nghệ hỗ trợ và vị trí của MADA trong hệ thống đó.','MADA (Mohammed bin Zayed AI Ambition? — không, tên đầy đủ là MADA-Qatar, viết tắt của tổ chức hỗ trợ người khuyết tật tại Qatar) là cơ quan chuyên trách về công nghệ hỗ trợ (AT) và năng lực vận động tại Qatar.

BỐI CẢNH:
Qatar là một trong những quốc gia đầu tư mạnh và sớm nhất vào lĩnh vực trợ giúp người khuyết tật, đặc biệt là hỗ trợ người mù và người khiếm thị. MADA ra đời từ nhu cầu đưa công nghệ hỗ trợ đến người dùng trên quy mô lớn, tập trung chính vào:
- Sàng lọc và đánh giá nhu cầu của trẻ em khuyết tật
- Cung cấp thiết bị công nghệ hỗ trợ
- Đào tạo người dùng và gia đình
- Cập nhật tiêu chuẩn AT theo thông lệ quốc tế

TIÊU CHUẨN ATSM (ATSM - Assistive Technology Standard of MADA):
MADA phát triển bộ tiêu chuẩn ATSM tương thích với tiêu chuẩn quốc tế, dùng làm cơ sở đánh giá chất lượng thiết bị AT. Nội dung ATSM bao gồm:
- Yêu cầu về an toàn và độ tin cậy thiết bị
- Tiêu chuẩn hiệu năng theo từng nhóm nhu cầu
- Quy trình đánh giá và chứng nhận thiết bị đạt chuẩn
- Hướng dẫn lựa chọn thiết bị phù hợp theo từng dạng khuyết tật

HỆ THỐNG WEBSITE at.mada.org.qa:
Đây là cổng thông tin công khai của MADA, liệt kê danh mục công nghệ hỗ trợ theo từng nhóm chuyên môn (thị giác, thính giác, giao tiếp, vận động, nhận thức) kèm thông số kỹ thuật và liên kết sản phẩm.','https://at.mada.org.qa/assistive-technology-portal/','web','https://at.mada.org.qa/assistive-technology-portal/',NULL,'regulatory-standards','[]',NULL,NULL,0,0.95,'published',2,'vi','{"botId":"bot-regulatory","madaCategory":"regulatory-standards","sourceCategory":"regulatory-standards","keywords":"atsm, mada, qatar, tiêu chuẩn mada, hỗ trợ người khuyết tật, chọn thiết bị, đánh giá nhu cầu","seededBy":"seed-regulatory-knowledge"}',0,NULL,'admin-1792403329191','2026-10-23T06:23:43.363Z','2026-10-23T06:23:43.363Z','ATSM Qatar — MADA standards and Qatar regulatory framework','','','Giới thiệu khung tiêu chuẩn ATSM của Qatar về công nghệ hỗ trợ và vị trí của MADA trong hệ thống đó.',NULL,NULL,'MADA (Mohammed bin Zayed AI Ambition? — không, tên đầy đủ là MADA-Qatar, viết tắt của tổ chức hỗ trợ người khuyết tật tại Qatar) là cơ quan chuyên trách về công nghệ hỗ trợ (AT) và năng lực vận động tại Qatar.

BỐI CẢNH:
Qatar là một trong những quốc gia đầu tư mạnh và sớm nhất vào lĩnh vực trợ giúp người khuyết tật, đặc biệt là hỗ trợ người mù và người khiếm thị. MADA ra đời từ nhu cầu đưa công nghệ hỗ trợ đến người dùng trên quy mô lớn, tập trung chính vào:
- Sàng lọc và đánh giá nhu cầu của trẻ em khuyết tật
- Cung cấp thiết bị công nghệ hỗ trợ
- Đào tạo người dùng và gia đình
- Cập nhật tiêu chuẩn AT theo thông lệ quốc tế

TIÊU CHUẨN ATSM (ATSM - Assistive Technology Standard of MADA):
MADA phát triển bộ tiêu chuẩn ATSM tương thích với tiêu chuẩn quốc tế, dùng làm cơ sở đánh giá chất lượng thiết bị AT. Nội dung ATSM bao gồm:
- Yêu cầu về an toàn và độ tin cậy thiết bị
- Tiêu chuẩn hiệu năng theo từng nhóm nhu cầu
- Quy trình đánh giá và chứng nhận thiết bị đạt chuẩn
- Hướng dẫn lựa chọn thiết bị phù hợp theo từng dạng khuyết tật

HỆ THỐNG WEBSITE at.mada.org.qa:
Đây là cổng thông tin công khai của MADA, liệt kê danh mục công nghệ hỗ trợ theo từng nhóm chuyên môn (thị giác, thính giác, giao tiếp, vận động, nhận thức) kèm thông số kỹ thuật và liên kết sản phẩm.','','',0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ('reg-assessing-needs','Quy trình đánh giá nhu cầu AT theo 7 nhóm chức năng','Hướng dẫn quy trình xác định loại công nghệ hỗ trợ phù hợp theo nhóm khuyết tật, giúp bot tư vấn đúng hướng điều trị.','Việc lựa chọn công nghệ hỗ trợ (AT) đúng phụ thuộc vào nhóm chức năng bị ảnh hưởng và mức độ khuyết tật, không chỉ bởi giá thiết bị.

BẢY NHÓM CHỨC NĂNG:

1. THỊ GIÁC (Vision): mù hoàn toàn, khiếm thị, nhìn mờ, mất thị lực một phần.
   Thiết bị thường dùng: kính lúp điện tử, máy đọc sách, trình đọc màn hình, chữ nổi Braille, máy chiếu.

2. THÍNH GIÁC (Hearing): điếc, nghe kém, ù tai, mất thính lực.
   Thiết bị: máy trợ thính, cấy ghép cochlear, thiết bị khuếch đại âm thanh, vòng cổ từ tính, hệ thống FM.

3. GIAO TIẾP & GIỌNG NÓI (Communication & Speech): nói khó, không nói được, sái khó nói (aphasia), mất giọng sau phẫu thuật thanh quản.
   Thiết bị: thiết bị giao tiếp tăng cường AAC, bảng giao tiếp, quảng bá hình ảnh, ứng dụng nói thay.

4. NHẬN THỨC & TÂM THẦN (Cognitive): trí nhớ suy giảm, chú ý kém, tự kỷ, hội chứng Down, thoái lui xã hội.
   Thiết bị: ứng dụng đơn giản hóa giao diện, trò chơi giáo dục, thiết bị ghi nhớ, bảng giao tiếp trực quan.

5. CƠ XƯƠNG KHỚP & VẬN ĐỘNG (Neuromusculoskeletal): thoát vị đĩa, đột quỵ, chấn thương tay, rung (tremor), cứng ngón.
   Thiết bị: nẹp chỉnh hình, bàn phím thay thế, chuột thay thế, nút bấm lớn, bàn tay giả.

6. DI CHUYỂN & ĐI LẠI (Mobility): liệt, yếu cơ, mất cân bằng, đau lưng, khó đi bộ xa.
   Thiết bị: xe lăn, xe lăn điện, khung đi, gậy, nạng, xe điện có hỗ trợ ghế.

7. SỐNG ĐỘC LẬP & AN TOÀN (Independent Living): sa mù, hồi quang, bệnh Alzheimer, người khuyết tật sống một mình.
   Thiết bị: thiết bị giám sát an toàn, báo động khẩn cấp, đồng hồ nhắc uống thuốc, đèn cảm biến chuyển động.

LƯU Ý VỀ CÁCH LỰA CHỌN:
- Luôn bắt đầu từ đánh giá nhu cầu thực tế của người dùng, không chọn thiết bị theo bệnh lý.
- Một người có thể cần thiết bị thuộc nhiều nhóm (ví dụ trẻ tự kỷ thường cần cả AT giao tiếp lẫn AT nhận thức).
- Thiết bị AT chỉ hiệu quả khi có đào tạo sử dụng cho người dùng và gia đình — đây là yếu tố bị bỏ qua phổ biến nhất.','https://at.mada.org.qa/assistive-technology-portal/','web','https://at.mada.org.qa/assistive-technology-portal/',NULL,'regulatory-standards','["ISO 9999"]',NULL,NULL,0,0.95,'published',2,'vi','{"botId":"bot-regulatory","madaCategory":"regulatory-standards","sourceCategory":"regulatory-standards","keywords":"đánh giá nhu cầu, chọn thiết bị, nhóm chức năng, phân loại khuyết tật, seven groups, at assessment, lập kế hoạch at","seededBy":"seed-regulatory-knowledge"}',0,NULL,'admin-1792403329191','2026-10-23T06:23:43.363Z','2026-10-23T06:23:43.363Z','Assistive technology needs assessment across 7 functional groups','','','Hướng dẫn quy trình xác định loại công nghệ hỗ trợ phù hợp theo nhóm khuyết tật, giúp bot tư vấn đúng hướng điều trị.',NULL,NULL,'Việc lựa chọn công nghệ hỗ trợ (AT) đúng phụ thuộc vào nhóm chức năng bị ảnh hưởng và mức độ khuyết tật, không chỉ bởi giá thiết bị.

BẢY NHÓM CHỨC NĂNG:

1. THỊ GIÁC (Vision): mù hoàn toàn, khiếm thị, nhìn mờ, mất thị lực một phần.
   Thiết bị thường dùng: kính lúp điện tử, máy đọc sách, trình đọc màn hình, chữ nổi Braille, máy chiếu.

2. THÍNH GIÁC (Hearing): điếc, nghe kém, ù tai, mất thính lực.
   Thiết bị: máy trợ thính, cấy ghép cochlear, thiết bị khuếch đại âm thanh, vòng cổ từ tính, hệ thống FM.

3. GIAO TIẾP & GIỌNG NÓI (Communication & Speech): nói khó, không nói được, sái khó nói (aphasia), mất giọng sau phẫu thuật thanh quản.
   Thiết bị: thiết bị giao tiếp tăng cường AAC, bảng giao tiếp, quảng bá hình ảnh, ứng dụng nói thay.

4. NHẬN THỨC & TÂM THẦN (Cognitive): trí nhớ suy giảm, chú ý kém, tự kỷ, hội chứng Down, thoái lui xã hội.
   Thiết bị: ứng dụng đơn giản hóa giao diện, trò chơi giáo dục, thiết bị ghi nhớ, bảng giao tiếp trực quan.

5. CƠ XƯƠNG KHỚP & VẬN ĐỘNG (Neuromusculoskeletal): thoát vị đĩa, đột quỵ, chấn thương tay, rung (tremor), cứng ngón.
   Thiết bị: nẹp chỉnh hình, bàn phím thay thế, chuột thay thế, nút bấm lớn, bàn tay giả.

6. DI CHUYỂN & ĐI LẠI (Mobility): liệt, yếu cơ, mất cân bằng, đau lưng, khó đi bộ xa.
   Thiết bị: xe lăn, xe lăn điện, khung đi, gậy, nạng, xe điện có hỗ trợ ghế.

7. SỐNG ĐỘC LẬP & AN TOÀN (Independent Living): sa mù, hồi quang, bệnh Alzheimer, người khuyết tật sống một mình.
   Thiết bị: thiết bị giám sát an toàn, báo động khẩn cấp, đồng hồ nhắc uống thuốc, đèn cảm biến chuyển động.

LƯU Ý VỀ CÁCH LỰA CHỌN:
- Luôn bắt đầu từ đánh giá nhu cầu thực tế của người dùng, không chọn thiết bị theo bệnh lý.
- Một người có thể cần thiết bị thuộc nhiều nhóm (ví dụ trẻ tự kỷ thường cần cả AT giao tiếp lẫn AT nhận thức).
- Thiết bị AT chỉ hiệu quả khi có đào tạo sử dụng cho người dùng và gia đình — đây là yếu tố bị bỏ qua phổ biến nhất.','','',0);
